            else if (!EqualityComparer<MissionCollectionId>.Default.Equals(_missionsRootScopeMissionCollection, missionCollection))
            {
                throw new InvalidOperationException(
                    "GS2Studio.Generated.Mission.MissionBinderCollection was already initialized with a different scope; cannot re-fetch the same child type under a new scope.");
            }
            var task = _missionsRootTask;
            GS2Studio.Generated.Mission.MissionBinderCollection root;
            try
            {
                root = await task;
            }
            catch
            {
                if (ReferenceEquals(_missionsRootTask, task)) _missionsRootTask = null;
                throw;
            }

            if (_disposed) { root.Dispose(); ThrowIfDisposed(); }
            _missionsRoot = root;
            return _missionsRoot;
        }

        private async Task<GS2Studio.Generated.Mission.MissionBinderCollection> BuildMissionsRootAsync(MissionCollectionId missionCollection, CancellationToken cancellationToken)
        {
            var root = await GS2Studio.Generated.Mission.MissionBinderCollection.CreateFromMissionMissionMasterDataAsync(_gs2, _session, missionCollection, cancellationToken);
            try { root.SubscribeFromMissionMissionMasterData(); }
            catch { root.Dispose(); throw; }
            return root;
        }
