        #region Model composition
        /// <summary>Mount, subscriptions and external stubs share this mapping so null-source resets stay consistent.</summary>
        public static void ApplyUserdataMissionMissionCounterModel(IMutableMissionCounter model, Gs2.Unity.Gs2Mission.Model.EzCounter? source)
        {
            if (source != null)
            {
                model.TodayValue = default;
                if (source.Values != null)
                {
                    var scopedValue = source.Values
                        .FirstOrDefault(v =>
                            v.ResetType == "daily" &&
                            v.ScopeType == "resetTiming");
                    if (scopedValue != null)
                    {
                        model.TodayValue = scopedValue.Value;
                    }
                }
                model.WeeklyValue = default;
                if (source.Values != null)
                {
                    var scopedValue2 = source.Values
                        .FirstOrDefault(v =>
                            v.ResetType == "weekly" &&
                            v.ScopeType == "resetTiming");
                    if (scopedValue2 != null)
                    {
                        model.WeeklyValue = scopedValue2.Value;
                    }
                }
                model.MonthlyValue = default;
                if (source.Values != null)
                {
                    var scopedValue3 = source.Values
                        .FirstOrDefault(v =>
                            v.ResetType == "monthly" &&
                            v.ScopeType == "resetTiming");
                    if (scopedValue3 != null)
                    {
                        model.MonthlyValue = scopedValue3.Value;
                    }
                }
                model.TotalValue = default;
                if (source.Values != null)
                {
                    var scopedValue4 = source.Values
                        .FirstOrDefault(v =>
                            v.ResetType == "notReset" &&
                            v.ScopeType == "resetTiming");
                    if (scopedValue4 != null)
                    {
                        model.TotalValue = scopedValue4.Value;
                    }
                }
            }
            else
            {
                model.TodayValue = default;
                model.WeeklyValue = default;
                model.MonthlyValue = default;
                model.TotalValue = default;
            }
        }

        #endregion

        #region MasterData reverse decode
        public static bool RestoreId(IMutableMissionCounter model, string actionName, string requestJson)
        {
            if (requestJson == null) return false;
            var request = JsonMapper.ToObject(requestJson);
            if (actionName == "Gs2Mission:IncreaseCounterByUserId")
            {
                var __value = ReadRequestValue(request, new string[] { "counterName" });
                if (__value != null)
                {
                    model.Id = (MissionCounterId)__value;
                    return true;
                }
            }
            return false;
        }

        private static string? ReadRequestValue(JsonData request, string[] segments)
        {
            JsonData current = request;
            foreach (var segment in segments)
            {
                if (current == null) return null;
                if (segment.Length >= 2 && segment[0] == '[' && segment[segment.Length - 1] == ']')
                {
                    if (!current.IsArray) return null;
                    if (!int.TryParse(segment.Substring(1, segment.Length - 2), out var index)) return null;
                    if (index < 0 || index >= current.Count) return null;
                    current = current[index];
                }
                else
                {
                    if (!current.IsObject || !current.Keys.Contains(segment)) return null;
                    current = current[segment];
                }
            }
            return current == null ? null : current.ToString();
        }
        #endregion

